(function() {
    'use strict';

    class ConductorAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `The Conductor's Dilemma`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.QUALITY_THRESHOLD = 75;     // renewal "satisfactory" line
            this.ATTENDANCE_TARGET = 78;     // renewal occupancy target
            this.HOUR_CAP = 320;             // rehearsal hours under the collective agreement
            this.OVERTIME_COST = 95;         // EUR / musician / hour beyond the cap
            this.MUSICIANS = 82;
            this.OCC_POINT_VALUE = 22000;    // EUR / occupancy point / season
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    quality: 62,
                    attendance: 64,
                    trust: 55,
                    overLeading: false,
                    hoursUsed: 0,
                    overtimeHours: 0,
                    overtimeCost: 0,
                    starOnboard: true,
                    authoritySurrendered: false,
                    qualityHistory: [62],
                    attendanceHistory: [64],
                    trustHistory: [55],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    posture: `calibrated`,
                    sections: `targeted`,
                    earn: 50,
                    tutti: 150,
                    sectional: 90,
                    overtime: 0,
                    regime: `craft`,
                    star: `coopt`,
                    fallback: `bench`,
                    credibility: 55,
                    gala: `balanced`,
                    defense: `reconcile`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const p = document.getElementById(`postureInput`);
                const s = document.getElementById(`sectionsInput`);
                const e = document.getElementById(`earnInput`);
                if (p) decisions.posture = p.value;
                if (s) decisions.sections = s.value;
                if (e) decisions.earn = parseInt(e.value, 10);
                if (!Number.isFinite(decisions.earn) || decisions.earn < 0 || decisions.earn > 100) {
                    warn(`warn_earn_range`); return false;
                }
            } else if (round === 2) {
                const fields = [[`tuttiInput`, `tutti`], [`sectionalInput`, `sectional`], [`overtimeInput`, `overtime`]];
                fields.forEach(([elId, key]) => {
                    const el = document.getElementById(elId);
                    if (el) decisions[key] = parseFloat(el.value);
                });
                const rg = document.getElementById(`regimeInput`);
                if (rg) decisions.regime = rg.value;
                const vals = [decisions.tutti, decisions.sectional, decisions.overtime];
                if (vals.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_hours_negative`); return false;
                }
                const inCap = decisions.tutti + decisions.sectional;
                if (inCap > this.HOUR_CAP + 0.001) {
                    warn(`warn_over_cap`); return false;
                }
                if (inCap < 120) {
                    warn(`warn_too_few_hours`); return false;
                }
            } else if (round === 3) {
                const st = document.getElementById(`starInput`);
                const fb = document.getElementById(`fallbackInput`);
                const cr = document.getElementById(`credibilityInput`);
                if (st) decisions.star = st.value;
                if (fb) decisions.fallback = fb.value;
                if (cr) decisions.credibility = parseInt(cr.value, 10);
                if (!Number.isFinite(decisions.credibility) || decisions.credibility < 0 || decisions.credibility > 100) {
                    warn(`warn_credibility_range`); return false;
                }
            } else if (round === 4) {
                const g = document.getElementById(`galaInput`);
                const df = document.getElementById(`defenseInput`);
                const cv = document.getElementById(`convictionInput`);
                if (g) decisions.gala = g.value;
                if (df) decisions.defense = df.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let qDelta = 0, aDelta = 0, tDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose direct vs enable. The OSL has drifted into laissez-faire; a calibrated
                // posture that names the weak sections and protects autonomy elsewhere is right.
                if (d.posture === `calibrated`) { tDelta += 8; qDelta += 2; coachKey = `coach_r1_calibrated`; }
                else if (d.posture === `directive`) { tDelta -= 12; qDelta += 3; ds.overLeading = true; coachKey = `coach_r1_directive`; }
                else if (d.posture === `enabling`) { tDelta += 4; qDelta -= 4; coachKey = `coach_r1_enabling`; }
                else { tDelta -= 4; qDelta -= 2; coachKey = `coach_r1_unsure`; }

                // Targeted diagnosis earns the right to intervene; drilling everyone signals control.
                if (d.sections === `targeted`) { qDelta += 6; tDelta += 4; }
                else if (d.sections === `all`) { tDelta -= 8; ds.overLeading = true; coachKey = (d.posture === `calibrated`) ? `coach_r1_calibrated_butall` : coachKey; }
                else { qDelta -= 4; coachKey = (d.posture === `enabling`) ? `coach_r1_enabling` : coachKey; }

                // Earning standing before using it (autonomy paradox). Too little = authority spent
                // before it is granted; a sensible amount builds trust without abdicating direction.
                if (d.earn >= 40 && d.earn <= 75) { tDelta += 8; }
                else if (d.earn < 25) { tDelta -= 6; coachKey = `coach_r1_norespect`; }
                else if (d.earn > 90) { qDelta -= 4; coachKey = `coach_r1_alllistening`; }

                summaryKey = (d.posture === `calibrated` && d.sections === `targeted`) ? `sum_r1_good` : (d.posture === `directive` || d.sections === `all` ? `sum_r1_overdirect` : `sum_r1_weak`);
            } else if (round === 2) {
                // Rehearsal discipline within the 320-hour cap. Sectionals are the highest
                // quality-per-hour lever; tutti is a costly baseline; overtime busts the cap.
                const tutti = d.tutti, sectional = d.sectional, overtime = d.overtime;
                ds.hoursUsed = tutti + sectional;
                ds.overtimeHours = overtime;
                ds.overtimeCost = Math.round(overtime * this.OVERTIME_COST * this.MUSICIANS);

                // Quality gains: sectionals convert ~2x better than tutti hours.
                qDelta += Math.round((sectional * 0.055 + tutti * 0.025) * 10) / 10;

                // Regime: craft converts discipline to quality without trust cost; strict drill
                // triggers the over-leading penalty and collapses trust; loose moves nothing.
                if (d.regime === `craft`) { tDelta += 8; qDelta += 4; coachKey = `coach_r2_craft`; }
                else if (d.regime === `strict`) {
                    ds.overLeading = true; tDelta -= 16; qDelta += 2; coachKey = `coach_r2_strict`;
                } else { tDelta += 2; qDelta -= 6; coachKey = `coach_r2_loose`; }

                // The over-leading penalty makes drilling hollow: hard quality gains are clawed back
                // when control has been substituted for craft (Facilitator Decision Tree).
                if (ds.overLeading) { qDelta = Math.round(qDelta * 0.5); }

                // Overtime beyond the cap: signals you cannot work within the constraint, costs
                // penalty pay, and erodes goodwill for diminishing quality returns.
                if (overtime > 0) {
                    ds.overLeading = true;
                    qDelta += Math.round(overtime * 0.05 * 10) / 10;
                    tDelta -= Math.round(6 + overtime * 0.12);
                    coachKey = `coach_r2_overtime`;
                }

                // Starving the diagnosed sections: all hours into full tutti misses the real lever.
                if (sectional < 40 && d.regime !== `strict` && overtime === 0) {
                    qDelta = Math.round(qDelta * 0.7);
                    coachKey = `coach_r2_nosectional`;
                }

                summaryKey = (d.regime === `craft` && overtime === 0 && sectional >= 60) ? `sum_r2_good` : (d.regime === `strict` || overtime > 0 ? `sum_r2_overdrill` : `sum_r2_weak`);
            } else if (round === 3) {
                // The star's pushback. Co-opting an ally or holding the line with respect both
                // preserve standing AND the gala pre-sale. Capitulating saves the night but
                // surrenders authority; pulling rank disengages the star and the principals.
                if (d.star === `coopt`) { tDelta += 10; aDelta += 6; qDelta += 3; ds.starOnboard = true; coachKey = `coach_r3_coopt`; }
                else if (d.star === `holdline`) { tDelta += 8; aDelta += 3; qDelta += 2; ds.starOnboard = true; coachKey = `coach_r3_holdline`; }
                else if (d.star === `capitulate`) { tDelta -= 20; aDelta += 7; qDelta -= 4; ds.starOnboard = true; ds.authoritySurrendered = true; coachKey = `coach_r3_capitulate`; }
                else if (d.star === `rank`) { tDelta -= 12; aDelta -= 12; qDelta -= 3; ds.starOnboard = false; coachKey = `coach_r3_rank`; }

                // Fallback only bites when the star is no longer reliably onboard (rank, or a fragile
                // capitulation). A real bench plan limits the attendance loss; no plan amplifies it.
                if (!ds.starOnboard || d.star === `rank`) {
                    if (d.fallback === `bench`) { aDelta += 8; tDelta += 4; coachKey = `coach_r3_bench`; }
                    else if (d.fallback === `poach`) { aDelta += 2; tDelta -= 4; coachKey = `coach_r3_poach`; }
                    else { aDelta -= 8; coachKey = `coach_r3_noplan`; }
                }

                // Pulling rank with no earned standing is the autonomy paradox made costly.
                if (d.star === `rank` && ds.trust < 55) { tDelta -= 6; }

                // Protecting credibility in front of the other 81 musicians.
                if (d.credibility >= 45 && d.credibility <= 80) { tDelta += 4; }
                else if (d.credibility < 25 && d.star === `capitulate`) { tDelta -= 6; }

                summaryKey = (d.star === `coopt` || d.star === `holdline`) ? `sum_r3_good` : (d.star === `capitulate` ? `sum_r3_surrender` : `sum_r3_rank`);
            } else if (round === 4) {
                // The gala calibration. Balanced is accessible without selling out; stacking pops
                // hits attendance but breaks the artistic threshold the same panel judges; an
                // all-purist programme protects quality but misses the occupancy number.
                if (d.gala === `balanced`) { aDelta += 8; qDelta += 4; tDelta += 2; coachKey = `coach_r4_balanced`; }
                else if (d.gala === `popsstack`) { aDelta += 14; qDelta -= 12; coachKey = `coach_r4_pops`; }
                else { qDelta += 8; aDelta -= 6; coachKey = `coach_r4_purist`; }

                // The mandate defence to the review panel.
                if (d.defense === `reconcile`) { tDelta += 8; qDelta += 2; aDelta += 2; coachKey = (d.gala === `balanced`) ? `coach_r4_reconcile` : coachKey; }
                else if (d.defense === `qualityonly`) { aDelta -= 4; tDelta -= 2; coachKey = `coach_r4_qualityonly`; }
                else { qDelta -= 6; aDelta -= 6; tDelta -= 8; coachKey = `coach_r4_excuses`; }

                // Conviction that authority over experts is earned through craft, not title.
                tDelta += Math.round((d.conviction - 60) / 10);

                summaryKey = (d.gala === `balanced` && d.defense === `reconcile`) ? `sum_r4_good` : (d.gala === `popsstack` ? `sum_r4_soldout` : `sum_r4_weak`);
            }

            // Trust feeds creative output (Edmondson, Amabile): when trust is collapsing, the
            // discretionary effort that produces artistic distinction is suppressed.
            if (ds.trust + tDelta < 35) { qDelta -= 4; }

            // Apply deltas with clamps.
            ds.quality = Math.max(0, Math.min(100, Math.round((ds.quality + qDelta) * 10) / 10));
            ds.attendance = Math.max(0, Math.min(100, Math.round((ds.attendance + aDelta) * 10) / 10));
            ds.trust = Math.max(0, Math.min(100, Math.round((ds.trust + tDelta) * 10) / 10));

            // Surrendering authority in public leaves a durable mark — the ensemble saw a new
            // leader back down, and that standing does not fully heal inside one season.
            if (ds.authoritySurrendered) ds.trust = Math.min(ds.trust, 62);

            ds.qualityHistory.push(Math.round(ds.quality));
            ds.attendanceHistory.push(Math.round(ds.attendance));
            ds.trustHistory.push(Math.round(ds.trust));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite to the reporting/grading layer each period; final period locks the score.
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                quality: Math.round(ds.quality),
                qualityDelta: Math.round(qDelta * 10) / 10,
                attendance: Math.round(ds.attendance),
                attendanceDelta: Math.round(aDelta * 10) / 10,
                trust: Math.round(ds.trust),
                trustDelta: Math.round(tDelta * 10) / 10,
                overLeading: ds.overLeading,
                hoursUsed: ds.hoursUsed,
                overtimeCost: ds.overtimeCost,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

