        // Composite 0-100 for the reporting/grading layer (results_utils.php reads
        // domainState.performance.overallScore). NEW in v1.1.0: the sim graded categorically
        // (outcome) and never emitted a number. Transparent weighted blend of the three tracked
        // 0-100 dimensions; the categorical outcome (which already encodes over-leading) stays the
        // qualitative grade. Weights: artistic quality .40, occupancy .30, ensemble trust .30.
        _composite(ds) {
            var q = Math.round(ds.quality || 0), a = Math.round(ds.attendance || 0), t = Math.round(ds.trust || 0);
            return Math.max(0, Math.min(100, Math.round(q * 0.40 + a * 0.30 + t * 0.30)));
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const quality = Math.round(ds.quality);
            const attendance = Math.round(ds.attendance);
            const trust = Math.round(ds.trust);

            const qualityMet = quality >= this.QUALITY_THRESHOLD;
            const attendanceMet = attendance >= this.ATTENDANCE_TARGET;
            const trustHeld = trust >= 40;
            const mandateRenewed = qualityMet && attendanceMet && trustHeld;

            // The over-leading penalty makes nominal quality untrustworthy to the panel: even a
            // high rating reads as forced if the ensemble has been over-controlled.
            const credibleQuality = qualityMet && !ds.overLeading;

            let outcome = `LostMandate`;
            if (mandateRenewed && credibleQuality && trust >= 60) outcome = `MandateRenewed`;
            else if (mandateRenewed) outcome = `RenewedOnTheWire`;
            else if (qualityMet && attendanceMet && !trustHeld) outcome = `WonNumbersLostEnsemble`;
            else if (qualityMet || attendanceMet) outcome = `OneThresholdShort`;

            const insights = [];
            if (outcome === `MandateRenewed`) insights.push(window.mySimulation.t(`insight_renewed`));
            else if (outcome === `RenewedOnTheWire`) insights.push(window.mySimulation.t(`insight_wire`));
            else if (outcome === `WonNumbersLostEnsemble`) insights.push(window.mySimulation.t(`insight_numberslost`));
            else if (outcome === `OneThresholdShort`) insights.push(window.mySimulation.t(`insight_oneshort`));
            else insights.push(window.mySimulation.t(`insight_lost`));

            if (ds.overLeading) insights.push(window.mySimulation.t(`insight_overleading`));
            if (trust < 40) insights.push(window.mySimulation.t(`insight_trustcollapse`));
            if (!ds.starOnboard) insights.push(window.mySimulation.t(`insight_starwalked`));
            if (qualityMet && attendanceMet && trust >= 60) insights.push(window.mySimulation.t(`insight_balance`));

            return {
                quality: quality,
                attendance: attendance,
                trust: trust,
                overLeading: ds.overLeading,
                mandateRenewed: mandateRenewed,
                starOnboard: ds.starOnboard,
                totalScore: this._composite(ds),
                overallScore: this._composite(ds),
                outcomeKey: outcome,
                outcome: window.mySimulation.t(`outcome_` + outcome),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.totalScore === 'number') ? s.totalScore
                : (typeof s.overallScore === 'number' ? s.overallScore : 0);
            var outcome = s.outcome || (s.outcomeKey ? T('outcome_' + s.outcomeKey) : '');
            var renewed = !!s.mandateRenewed;
            var badge = renewed
                ? '<span class="cd-cm-badge cd-cm-yes">' + T('cm_mandate_renewed') + '</span>'
                : '<span class="cd-cm-badge cd-cm-no">' + T('cm_mandate_lost') + '</span>';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="cd-cm-metric"><span class="cd-cm-mv">' + Math.round(s.quality||0) + '</span><span class="cd-cm-ml">' + T('cm_m_quality') + '</span></div>'
                + '<div class="cd-cm-metric"><span class="cd-cm-mv">' + Math.round(s.attendance||0) + '%</span><span class="cd-cm-ml">' + T('cm_m_attendance') + '</span></div>'
                + '<div class="cd-cm-metric"><span class="cd-cm-mv">' + Math.round(s.trust||0) + '</span><span class="cd-cm-ml">' + T('cm_m_trust') + '</span></div>';
            return ''
                + '<div class="cd-completion">'
                +   '<div class="cd-cm-head">'
                +     '<div class="cd-cm-score">' + score + '<span class="cd-cm-score-max">/100</span></div>'
                +     '<div class="cd-cm-grade">' + outcome + ' ' + badge + '</div>'
                +   '</div>'
                +   '<div class="cd-cm-metrics">' + metrics + '</div>'
                +   '<div class="cd-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="cd-cm-insights">' + items + '</ul>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.overLeading && state.currentPeriod >= 2) return window.mySimulation.t(`hint_overleading`);
            if (ds.trust < 40) return window.mySimulation.t(`hint_trust`);
            if (!ds.starOnboard) return window.mySimulation.t(`hint_star`);
            if (ds.quality < this.QUALITY_THRESHOLD && state.currentPeriod >= 3) return window.mySimulation.t(`hint_quality`);
            if (ds.attendance < this.ATTENDANCE_TARGET && state.currentPeriod >= 3) return window.mySimulation.t(`hint_attendance`);
            if (ds.quality >= this.QUALITY_THRESHOLD && ds.attendance >= this.ATTENDANCE_TARGET && ds.trust >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

