                    warn_earn_range:        `Time spent earning standing must be a percentage between 0 and 100.`,
                    warn_hours_negative:    `Rehearsal hours cannot be negative.`,
                    warn_over_cap:          `Tutti + sectional hours exceed the 320-hour cap. Move drilling into overtime explicitly, or re-balance.`,
